    def test_add_seconds_2(self):
        # Docstring example: with the current time 19:19:22, add_seconds(600) returns "19:29:22".
        fixed_now = datetime.datetime(2023, 6, 14, 19, 19, 22)

        class FixedDatetime(datetime.datetime):
